// ═══ HTTP/3 CLIENT (JDK 25+) ═══
HttpClient http3Client = HttpClient.newBuilder()
    .version(HttpClient.Version.HTTP_3)       // prefer HTTP/3 (QUIC)
    .connectTimeout(Duration.ofSeconds(5))
    .build();

HttpRequest request = HttpRequest.newBuilder()
    .uri(URI.create("https://api.bank.com/trades"))
    .GET()
    .build();

// Async request over HTTP/3:
http3Client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
    .thenApply(HttpResponse::body)
    .thenAccept(body -> log.info("Response: {}", body));

// ═══ FALLBACK: HTTP/3 → HTTP/2 → HTTP/1.1 ═══
// If server doesn't support HTTP/3, client automatically falls back to HTTP/2
// No code change needed — version negotiation is automatic
