// File: src/test/java/com/bank/java8/Http3Test.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.net.http.HttpClient;
import static org.assertj.core.api.Assertions.assertThat;

class Http3Test {

    // Picks the preferred protocol version for the client.
    String protocolPreference(boolean lossyNetwork) {
        return lossyNetwork ? "HTTP_3" : "HTTP_2";
    }

    @Test
    void prefersHttp3OnLossyNetwork() {
        assertThat(protocolPreference(true)).isEqualTo("HTTP_3");
        assertThat(protocolPreference(false)).isEqualTo("HTTP_2");
        // existing HttpClient API is unchanged across versions
        assertThat(HttpClient.newBuilder().build()).isNotNull();
    }
}
